import os, glob, re

def load_grids_from_logs():
    """Load grids from session logs - demo pairs given so far."""
    rlm_session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not rlm_session_dir:
        return {}

    # Find the session log file for this specific instance
    session_file = os.path.join(rlm_session_dir, '..', 'sessions', os.path.basename(rlm_session_dir) + '.jsonl')
    if not os.path.exists(session_file):
        # Try to find any .jsonl file in parent
        parent = os.path.dirname(rlm_session_dir)
        candidates = glob.glob(os.path.join(parent, '*.jsonl'))
        if candidates:
            session_file = candidates[0]

    G = {}
    if os.path.exists(session_file):
        content = open(session_file).read()
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in content[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids_from_logs()
print("Loaded demo pairs:", list(G.keys()))
for k, grid in sorted(G.items()):
    print(f"\n{grid[0] if isinstance(grid, list) and grid else 'N/A'}")  # show row[0]

